edits.newText:
final playingExists =
    playingPath != null && playingPath.isNotEmpty;
final divergent = playingExists &&
    p.dirname(playingPath!) != (path ?? '');
final isLinux = Theme.of(context).platform ==
    TargetPlatform.linux;

// On Linux, keep the action available even when the playing
// track's parent is already the current browser folder so
// we can bring an off-screen row into view.
final showJumpGlyph = isLinux
    ? playingExists
    : resolveJumpGlyphVisible(divergent);

